pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 value) public {
        vm.assume(sender != address(0));
        vm.assume(value > 0 && value <= address(c).balance + 1 ether); // prevent overflow/revert in send
        vm.deal(sender, value);
        vm.prank(sender);

        uint256 balanceBefore = address(c).balance;

        // call sendMoney as owner
        vm.prank(c.owner());
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", sender, value));

        // Only consider successful sends
        vm.assume(success);

        uint256 balanceAfter = address(c).balance;

        // Now withdraw all
        vm.prank(c.owner());
        c.withdrawAll();

        uint256 balanceAfterWithdraw = address(c).balance;

        // General rule: after sendMoney and then withdrawAll, the contract balance should go back to original (or less due to gas, but here exactly)
        // For reference: withdrawAll sends the entire balance to owner, so final balance should be 0 (or minimal if owner is contract itself).
        // Simplified: balanceAfter - balanceBefore == value, and after withdrawAll balance becomes 0.
        assertTrue(balanceAfter - balanceBefore == value && balanceAfterWithdraw == 0);
    }
}

