pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value) public {
        // bound value to avoid overflow issues
        _value = bound(_value, 0, address(c).balance);

        // record initial balance
        uint256 initialBalance = address(c).balance;
        uint256 initialDeposits = c.depositsCount();

        // call sendMoney, which might revert or succeed
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", _target, _value));

        // after the call, compute expected balance
        // Each call to sendMoney does not change depositsCount, but the fallback is never triggered here because msg.value=0
        // However, if the transfer inside withdrawAll() or withdraw() were called, that could change balance.
        // But sendMoney only calls _target.call{value:_value}("") so if it succeeds, contract balance decreases by _value.
        // If it reverts, balance stays same.
        uint256 expectedBalance;
        if (success) {
            expectedBalance = initialBalance - _value;
        } else {
            expectedBalance = initialBalance;
        }

        // Also, depositsCount should remain unchanged because no fallback was triggered
        uint256 finalDeposits = c.depositsCount();
        assertTrue(finalDeposits == initialDeposits && address(c).balance == expectedBalance, "Balance invariant violated");
    }
}

